<?php declare(strict_types=1); ?>
<div class="mod-wrap"><?php if ($reports === []): ?><p>No reports to review.</p><?php endif ?><?php foreach ($reports as $report): ?><fieldset><legend>Report #<?= $v::e($report['id']) ?></legend><p><a href="<?= $v->url('mod.php?view=post&id=' . $report['post_id']) ?>">Manage /<?= $v::e($report['slug']) ?>/<?= $v::e($report['post_id']) ?> — <?= $v::e($report['subject']) ?></a></p><p><?= $v::e($report['reason']) ?></p><small><?= gmdate('Y-m-d H:i:s', (int) $report['created']) ?> UTC</small><form class="compact" action="<?= $v->url('mod.php') ?>" method="post"><?= $v->csrf() ?><input name="id" type="hidden" value="<?= $v::e($report['id']) ?>"><button name="action" value="report-dismiss">Dismiss report</button></form></fieldset><?php endforeach ?></div>
